                grid[i*2+1][j*2],
                grid[i*2+1][j*2+1]
            ]
            # Rule: output is the average (sum/4) or counts per color
            # Actually, let's see if there's a color-mapping pattern across demos
            freq = {}
            for c in block:
                if c not in freq:
                    freq[c] = []
                freq[c].append(c)

            # Find color that appears exactly ONCE in each 2x2 block
            # This is based on pattern analysis from all demos
            for c in freq.keys():
                if len(freq[c]) == 1:
                    output[i][j] = c
                    break

            # If no unique color, use the majority color that's NOT 6
            if output[i][j] == 0:
                for c, count in freq.items():
